"""Standalone local rating page; it contains no source labels or answer key."""
import argparse,json
from pathlib import Path

p=argparse.ArgumentParser();p.add_argument('directory');a=p.parse_args();root=Path(a.directory)
trials=json.loads((root/'trials.json').read_text(encoding='utf-8'))
html=r'''<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>音乐编排盲评</title>
<style>body{font:16px system-ui;background:#08101d;color:#e4edf6;margin:24px auto;padding:0 18px;max-width:1200px}section{padding:20px;border:1px solid #314054;border-radius:12px;margin:24px 0}.pair{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,320px),1fr));gap:20px}video{width:100%}label{margin-right:22px}button,input{font:inherit;padding:8px}button{cursor:pointer}h2{font-size:21px}</style>
<h1>音乐编排盲评</h1><p>每组是同一首歌的两个完整版本。请带音频观看，再比较卡点、构图、连贯性、多样性和继续观看意愿。可以暂不评价任何未看过的组。A/B 每项可分别打 1–5 分，也可以留空。此页面不会上传数据。</p>
<label>匿名参与者编号 <input id="participant" maxlength="60"></label><div id="trials"></div><button id="save">保存本地评价 CSV</button><p id="status"></p>
<script>const trials=__TRIALS__;
for(const t of trials){const s=document.createElement('section'),title=document.createElement('h2');title.textContent=`第 ${t.trial} 组`;s.append(title);const grid=document.createElement('div');grid.className='pair';for(const side of ['A','B']){const box=document.createElement('div'),v=document.createElement('video');v.src=t[side];v.controls=true;v.preload='metadata';v.onplay=()=>document.querySelectorAll('video').forEach(x=>{if(x!==v)x.pause()});const name=document.createElement('p');name.textContent=side;box.append(name,v);grid.append(box)}s.append(grid);for(const side of ['A','B','TIE']){const l=document.createElement('label'),r=document.createElement('input');r.type='radio';r.name='trial-'+t.trial;r.value=side;l.append(r,side==='TIE'?'相当':`偏好 ${side}`);s.append(l)}const ratings=document.createElement('div');ratings.style.marginTop='20px';for(const [key,name] of [['timing','卡点'],['composition','构图'],['coherence','连贯性'],['diversity','多样性'],['watch_again','继续观看意愿']]){const row=document.createElement('div');row.style.margin='10px 0';row.append(name+' ');for(const side of ['A','B']){const l=document.createElement('label'),select=document.createElement('select');select.name=`rating-${t.trial}-${side}-${key}`;for(const v of ['','1','2','3','4','5']){const o=document.createElement('option');o.value=v;o.textContent=v||'未评';select.append(o)}l.append(side+' ',select);row.append(l)}ratings.append(row)}s.append(ratings);document.querySelector('#trials').append(s)}
document.querySelector('#save').onclick=()=>{const id=document.querySelector('#participant').value.trim();if(!id){document.querySelector('#status').textContent='请填写匿名参与者编号';return}const keys=['timing','composition','coherence','diversity','watch_again'],fields=['A','B'].flatMap(side=>keys.map(k=>side+'_'+k));const rows=[['participant','trial','preference',...fields]];for(const t of trials){const r=document.querySelector(`input[name="trial-${t.trial}"]:checked`),scores=['A','B'].flatMap(side=>keys.map(k=>document.querySelector(`select[name="rating-${t.trial}-${side}-${k}"]`).value));if(r||scores.some(x=>x!==''))rows.push([id,String(t.trial),r?.value||'',...scores])}if(rows.length===1){document.querySelector('#status').textContent='尚未选择任何已观看的组';return}const csv=rows.map(r=>r.map(x=>'"'+x.replaceAll('"','""')+'"').join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}));a.download='blind-votes.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);document.querySelector('#status').textContent=`已保存 ${rows.length-1} 组实际选择。未选的组不计入结果。`};</script>'''
(root/'index.html').write_text(html.replace('__TRIALS__',json.dumps(trials,separators=(',',':'))),encoding='utf-8')
print('Created anonymous local rating page for',len(trials),'pairs')
